// Map the form fields to the episode brief stored in Postgres (D-050). Validation lives in SQL
// (brief_normalize), so an invalid brief fails the execution and WF-99 reports it. The full brief
// is passed as typed: its narration must stay verbatim.
const form = $input.first().json;
const text = (label) => {
  const value = form[label];
  return typeof value === 'string' && value.trim() !== '' ? value.trim() : undefined;
};
const minutes = form['Duration (minutes)'];
const brief = {
  format: 'episode',
  topic: text('Topic'),
  duration_minutes: minutes === '' || minutes == null ? undefined : Number(minutes),
  full_brief: typeof form['Full brief'] === 'string' && form['Full brief'].trim() !== '' ? form['Full brief'] : undefined,
  notes: text('Notes'),
};
return [{ json: { submissionId: `n8n-form-${$execution.id}`, brief: JSON.stringify(brief) } }];

const row = $input.first().json;
const shortId = String(row.video_id).slice(0, 8);
const verb = row.created ? 'New video submitted' : 'Duplicate form submission ignored';
return [{ json: { text: `[AI Video] ${verb}\nVideo ${shortId} v1: scripting` } }];
